-- KeySuite V1.00 Company & Pricing schema and seed data
begin;
create table if not exists ks_companies (
  id text primary key,
  company_name text not null,
  pricing_category text,
  delivery_distance numeric default 0,
  company_phone text,
  term_days integer,
  address text,
  tin_number text,
  business_registration_no text,
  sst_no text,
  msic_code text,
  business_activities text
);
create table if not exists ks_company_users (
  id text primary key,
  company_id text not null references ks_companies(id),
  source_company_id text,
  prefix text,
  full_name text not null,
  phone text,
  email text
);
create table if not exists ks_pricing_categories (
  id text primary key,
  category_name text unique not null,
  final_discount numeric not null default 0,
  set_discount numeric not null default 0,
  commission numeric not null default 0,
  chc_factor numeric not null default 1,
  transport numeric not null default 0
);
create table if not exists ks_products_chc (
  id text primary key,
  product_category text not null default 'CHC',
  model text not null,
  chc_usd numeric,
  chcs_usd numeric,
  chcn_usd numeric,
  source_row integer
);
create index if not exists ks_products_chc_model_idx on ks_products_chc(model);
commit;
